//! Source locations and event dates are derived from stored metadata, never generated by the model.
use crate::domain::{Audience, Hit, RagError, Result};
use chrono::{DateTime, FixedOffset, NaiveDate, Utc};
use serde::Serialize;
use serde_json::Value;
use sqlx::PgPool;
use std::collections::BTreeMap;

#[derive(Debug, Clone, Serialize)]
pub struct SourceLink {
    pub label: String,
    pub url: String,
}

#[derive(Debug, Clone, Serialize)]
pub struct Reference {
    pub doc_id: String,
    pub title: String,
    pub heading: String,
    pub content_preview: String,
    pub relevance_score: f32,
    pub source_type: String,
    pub url: String,
    pub source_links: Vec<SourceLink>,
    pub occurred_at: Option<String>,
    pub indexed_at: i64,
    pub commit_shas: Vec<String>,
    pub repository_id: Option<String>,
}

pub fn component(value: &str) -> String {
    value
        .bytes()
        .map(|byte| {
            if byte.is_ascii_alphanumeric() || matches!(byte, b'-' | b'_' | b'.' | b'~') {
                char::from(byte).to_string()
            } else {
                format!("%{byte:02X}")
            }
        })
        .collect()
}

pub fn safe_url(value: &str) -> Option<String> {
    if value.is_empty() || value.len() > 4096 || value.chars().any(char::is_control) {
        return None;
    }
    let relative = value.starts_with('/') && !value.starts_with("//") && !value.contains('\\');
    let parsed =
        reqwest::Url::parse(if relative { "https://source.invalid" } else { value }).ok()?;
    let parsed = if relative { parsed.join(value).ok()? } else { parsed };
    if parsed.query_pairs().any(|(key, _)| {
        ["token", "access_token", "api_key", "apikey", "password", "secret", "authorization"]
            .contains(&key.to_lowercase().as_str())
    }) {
        return None;
    }
    (matches!(parsed.scheme(), "http" | "https")
        && parsed.host_str().is_some()
        && parsed.username().is_empty()
        && parsed.password().is_none())
    .then(|| if relative { value.to_owned() } else { parsed.to_string() })
}

fn event_date(source_type: &str, metadata: &Value) -> Option<String> {
    let value = match source_type {
        "git_activity" => metadata.get("date")?,
        "yunxiao_requirement" | "yunxiao_testcase" | "onboarding" => metadata.get("updatedAt")?,
        _ => return None,
    };
    if let Some(value) = value.as_str() {
        if let Ok(date) = NaiveDate::parse_from_str(value, "%Y-%m-%d") {
            return Some(date.to_string());
        }
        if let Ok(date) = DateTime::parse_from_rfc3339(value) {
            return Some(date.with_timezone(&FixedOffset::east_opt(8 * 3600)?).to_rfc3339());
        }
    }
    let number = value.as_i64().or_else(|| value.as_str()?.parse().ok())?;
    DateTime::<Utc>::from_timestamp_millis(number).map(|date| {
        date.with_timezone(&FixedOffset::east_opt(8 * 3600).expect("Shanghai offset")).to_rfc3339()
    })
}

pub fn reference(
    project: &str,
    hit: &Hit,
    source_type: &str,
    source_id: Option<&str>,
    indexed_at: i64,
) -> Reference {
    let metadata: Value =
        source_id.and_then(|value| serde_json::from_str(value).ok()).unwrap_or(Value::Null);
    let internal = format!(
        "/p/{}/chat?document={}&chunk={}",
        component(project),
        component(&hit.document_id),
        component(&hit.chunk_id)
    );
    let mut links = Vec::new();
    for key in ["sourceUrl", "webUrl", "url"] {
        if let Some(url) = metadata.get(key).and_then(Value::as_str).and_then(safe_url) {
            links.push(SourceLink { label: "原始来源".into(), url });
            break;
        }
    }
    if source_type.starts_with("yunxiao_") {
        if let (Some(source), Some(external)) =
            (metadata["sourceId"].as_str(), metadata["externalId"].as_str())
        {
            let url = if source_type == "yunxiao_requirement" {
                format!(
                    "/devops?source={}&view=delivery&reference={}",
                    component(source),
                    component(external)
                )
            } else {
                format!(
                    "/devops?source={}&view=records&kind=testcase&search={}",
                    component(source),
                    component(metadata["serial"].as_str().unwrap_or(external))
                )
            };
            links.push(SourceLink { label: "云效来源记录".into(), url });
        }
    }
    for entry in metadata["commitRefs"].as_array().into_iter().flatten().take(12) {
        if let Some(url) = entry["url"].as_str().and_then(safe_url) {
            let label = entry["sha"]
                .as_str()
                .map(|sha| sha.chars().take(12).collect::<String>())
                .unwrap_or_else(|| "来源提交".into());
            if !links.iter().any(|link| link.url == url) {
                links.push(SourceLink { label, url });
            }
        }
    }
    let mut commit_shas = Vec::new();
    if let Some(sha) = metadata["commit"]
        .as_str()
        .filter(|value| value.len() == 40 && value.bytes().all(|byte| byte.is_ascii_hexdigit()))
    {
        commit_shas.push(sha.to_lowercase());
    }
    if source_type == "git_activity" {
        let pattern = regex::Regex::new(r"\b[0-9a-fA-F]{40}\b").expect("commit pattern");
        for found in pattern.find_iter(&format!("{}\n{}", hit.heading, hit.content)) {
            let sha = found.as_str().to_lowercase();
            if !commit_shas.contains(&sha) {
                commit_shas.push(sha);
            }
            if commit_shas.len() >= 8 {
                break;
            }
        }
    }
    Reference {
        doc_id: hit.document_id.clone(),
        title: if source_type == "onboarding" {
            metadata["version"]
                .as_u64()
                .map(|version| format!("{} · v{}", hit.title, version))
                .unwrap_or_else(|| hit.title.clone())
        } else {
            hit.title.clone()
        },
        heading: hit.heading.clone(),
        content_preview: hit.content.chars().take(4096).collect(),
        relevance_score: hit.score,
        source_type: source_type.into(),
        url: links.first().map(|link| link.url.clone()).unwrap_or(internal),
        source_links: links,
        occurred_at: event_date(source_type, &metadata),
        indexed_at,
        commit_shas,
        repository_id: metadata["repositoryId"].as_str().map(str::to_owned),
    }
}

pub fn recency_requested(question: &str) -> bool {
    ["最近", "最新", "按时间", "升级", "生产", "报错"].iter().any(|word| question.contains(word))
}

pub fn date_key(source: &Reference) -> i64 {
    let Some(value) = source.occurred_at.as_deref() else {
        return i64::MIN;
    };
    DateTime::parse_from_rfc3339(value)
        .map(|date| date.timestamp_millis())
        .ok()
        .or_else(|| {
            NaiveDate::parse_from_str(value, "%Y-%m-%d")
                .ok()?
                .and_hms_opt(0, 0, 0)
                .map(|date| date.and_utc().timestamp_millis())
        })
        .unwrap_or(i64::MIN)
}

pub async fn load(
    pool: &PgPool,
    project: &str,
    hits: &[Hit],
    audience: &Audience,
) -> Result<Vec<Reference>> {
    if hits.is_empty() {
        return Ok(Vec::new());
    }
    let ids: Vec<_> = hits.iter().map(|hit| hit.document_id.clone()).collect();
    let rows: Vec<(String, String, Option<String>, i64)> = sqlx::query_as(
        "SELECT id, source_type, source_id, updated_at FROM ms_rag_document WHERE project_id=$1 AND id=ANY($2) \
         AND ($3 OR owner_id=$4 OR visibility_groups && $5::text[])"
    ).bind(project).bind(&ids).bind(audience.is_admin).bind(&audience.user_id).bind(&audience.visible_group_ids)
        .fetch_all(pool).await.map_err(|error| RagError::Backend(error.to_string()))?;
    let metadata: BTreeMap<_, _> =
        rows.into_iter().map(|(id, kind, source, updated)| (id, (kind, source, updated))).collect();
    hits.iter()
        .map(|hit| {
            let (kind, source, updated) = metadata.get(&hit.document_id).ok_or_else(|| {
                RagError::Backend("source visibility changed during retrieval".into())
            })?;
            Ok(reference(project, hit, kind, source.as_deref(), *updated))
        })
        .collect()
}

#[cfg(test)]
mod tests {
    use super::*;
    fn hit() -> Hit {
        Hit {
            chunk_id: "chunk".into(),
            document_id: "doc".into(),
            title: "Document".into(),
            heading: String::new(),
            content: "Evidence".into(),
            score: 0.5,
        }
    }
    #[test]
    fn unsafe_or_credential_urls_are_not_exposed() {
        for value in [
            "javascript:alert(1)",
            "//evil.invalid",
            "https://user:password@example.com/",
            "/\\evil.invalid",
            "https://example.com/\nsecret",
        ] {
            assert!(safe_url(value).is_none());
        }
        assert_eq!(safe_url("/devops?source=test").as_deref(), Some("/devops?source=test"));
    }
    #[test]
    fn unknown_sources_use_an_authorized_document_view() {
        let source = reference("project", &hit(), "manual", None, 42);
        assert_eq!(source.url, "/p/project/chat?document=doc&chunk=chunk");
        assert!(source.occurred_at.is_none());
        assert_eq!(source.indexed_at, 42);
    }
    #[test]
    fn git_dates_do_not_use_the_indexing_clock() {
        let source = reference(
            "project",
            &hit(),
            "git_activity",
            Some(
                r#"{"date":"2026-11-04","commitRefs":[{"sha":"abc123","url":"https://example.com/commit/abc123"}]}"#,
            ),
            100,
        );
        assert_eq!(source.occurred_at.as_deref(), Some("2026-11-04"));
        assert_eq!(source.url, "https://example.com/commit/abc123");
    }
    #[test]
    fn workitem_references_escape_the_source_identity() {
        let source = reference(
            "project",
            &hit(),
            "yunxiao_requirement",
            Some(r#"{"sourceId":"source & extra","externalId":"item/1"}"#),
            1,
        );
        assert!(source.url.contains("source%20%26%20extra"));
        assert!(source.url.contains("item%2F1"));
    }
}
